INSERT INTO lessons VALUES('P2B-U05-L1',2,'practical-order-aliases-v2',2,'B',5,'用and连起两件事','{"id":"P2B-U05-L1","unitId":"P2B-U05","grade":2,"term":"B","unitNumber":5,"unitLesson":1,"order":17,"subtitle":"下学期第五站：读懂天气、清单与计划，用依据修订表达","minutes":10,"title":"用and连起两件事","homeActivity":"画两件自己会做的收拾动作，用and连起来说一句。不需要为了练英语额外做家务。","releaseId":"practical-order-aliases-v2","unitTitle":"好习惯","cards":[{"title":"用and连起两件事","rule":"and可以连接两个词或两件事，常表示和、并且。I wash and dry my hands连接两个动作。看清前后都是补充信息时可用and；连接词表达关系，不替代每句需要的动作词。","example":"I wash and dry my hands.","translation":"我洗手并擦干。"},{"title":"用and连起两件事","rule":"and可以连接两个词或两件事，常表示和、并且。I wash and dry my hands连接两个动作。看清前后都是补充信息时可用and；连接词表达关系，不替代每句需要的动作词。","example":"Nora packs a towel and a comb.","translation":"Nora装好毛巾和梳子。"},{"title":"用and连起两件事","rule":"and可以连接两个词或两件事，常表示和、并且。I wash and dry my hands连接两个动作。看清前后都是补充信息时可用and；连接词表达关系，不替代每句需要的动作词。","example":"We clean the tray and put it away.","translation":"我们清洁托盘并收好。"}],"vocabulary":[{"word":"and","meaning":"和；并且"},{"word":"wash","meaning":"洗"},{"word":"dry","meaning":"擦干；干的"},{"word":"towel","meaning":"毛巾"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.connectives","grammar.be","sentence.patterns.time"],"itemCount":9,"version":2}');
INSERT INTO lessons VALUES('P2B-U05-L4',2,'practical-order-aliases-v2',2,'B',5,'读懂习惯小清单','{"id":"P2B-U05-L4","unitId":"P2B-U05","grade":2,"term":"B","unitNumber":5,"unitLesson":4,"order":20,"subtitle":"下学期第五站：读懂天气、清单与计划，用依据修订表达","minutes":10,"title":"读懂习惯小清单","homeActivity":"画一张虚构出门清单，和家人分别说清楚清单写了什么、没有写什么。","releaseId":"practical-order-aliases-v2","unitTitle":"好习惯","cards":[{"title":"读懂习惯小清单","rule":"读日常清单先找人物和动作，再看and补充、but转折。清单里没写的事不能自己加上；不同家庭的安排也可能不同。本课练读懂句子，不给健康打分。","example":"Lina packs her bag and checks her bottle.","translation":"Lina装好书包并检查水杯。"},{"title":"读懂习惯小清单","rule":"读日常清单先找人物和动作，再看and补充、but转折。清单里没写的事不能自己加上；不同家庭的安排也可能不同。本课练读懂句子，不给健康打分。","example":"Her bag is ready, but her bottle is empty.","translation":"她的书包准备好了，但水杯是空的。"},{"title":"读懂习惯小清单","rule":"读日常清单先找人物和动作，再看and补充、but转折。清单里没写的事不能自己加上；不同家庭的安排也可能不同。本课练读懂句子，不给健康打分。","example":"The list does not say the time.","translation":"清单没有写时间。"}],"vocabulary":[{"word":"list","meaning":"清单"},{"word":"check","meaning":"检查"},{"word":"empty","meaning":"空的"},{"word":"bottle","meaning":"瓶；水杯"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.connectives","grammar.be","sentence.patterns.time"],"itemCount":9,"version":2}');
INSERT INTO items VALUES('P2B-U05-L1.p9.order',2,'P2B-U05-L1',2,'grammar.connectives.addition','controlled-production','order','{"title":"用and连起两件事","gradeMin":2,"id":"P2B-U05-L1.p9.order","type":"order","category":"grammar","context":"从I pack开头，表达装好毛巾和梳子。","prompt":"先用“I pack”开头，再按情景排列其余词块，最后放好标点。","tokens":[".","comb","a","and","towel","a","pack","I"],"punctuationTokens":true}','{"answers":["I pack a towel and a comb.","I pack a comb and a towel."],"family":"fact-eef73f7e333e333d","hint":"and可以连接两个词或两件事，常表示和、并且。I wash and dry my hands连接两个动作。看清前后都是补充信息时可用and；连接词表达关系，不替代每句需要的动作词。","explanation":"I pack a towel and a comb. 从I pack开头，表达装好毛巾和梳子。 and可以连接两个词或两件事，常表示和、并且。I wash and dry my hands连接两个动作。看清前后都是补充信息时可用and；连接词表达关系，不替代每句需要的动作词。","solutionSentences":["I pack a towel and a comb.","I pack a comb and a towel."]}','published');
