INSERT INTO items VALUES('P2B-U05-L4.p9.order',2,'P2B-U05-L4',2,'grammar.connectives.addition','controlled-production','order','{"title":"读懂习惯小清单","gradeMin":2,"id":"P2B-U05-L4.p9.order","type":"order","category":"grammar","context":"从We pack开头，说装好布袋和杯子。","prompt":"先用“We pack”开头，再按情景排列其余词块，最后放好标点。","tokens":[".","cup","a","and","bag","cloth","a","pack","We"],"punctuationTokens":true}','{"answers":["We pack a cloth bag and a cup.","We pack a cup and a cloth bag."],"family":"fact-20d657c9893f8ba4","hint":"读日常清单先找人物和动作，再看and补充、but转折。清单里没写的事不能自己加上；不同家庭的安排也可能不同。本课练读懂句子，不给健康打分。","explanation":"We pack a cloth bag and a cup. 从We pack开头，说装好布袋和杯子。 读日常清单先找人物和动作，再看and补充、but转折。清单里没写的事不能自己加上；不同家庭的安排也可能不同。本课练读懂句子，不给健康打分。","solutionSentences":["We pack a cloth bag and a cup.","We pack a cup and a cloth bag."]}','published');
